def add(f,n,e,m,c,req,data,status,oracle,src='AI-001',label='VALID',reason='Contract-aligned, executable, oracle defined'):
    if src.startswith('AI') and '/' in status:
        label='INCOMPLETE'; reason='AI supplied multiple possible statuses; human must resolve exact oracle from contract/run'; corrected='Split into separate cases or document one normative expected result'
    else:
        corrected=''
    R.append([f'{f}-{n:03d}',f,e,m,c,req,'Seed data + required actor token',data,'Send request; assert status/body/schema; verify postcondition',status,oracle,src,label,reason,corrected,'Pending Newman mapping','Not executed','', 'Pending authentic evidence'])

