pre=["pm.request.headers.upsert({key:'X-Student-Id',value:pm.environment.get('studentId')||'23127326'});","pm.request.headers.upsert({key:'Content-Type',value:'application/json'});"]
def t(code,label): return [f"pm.test('{label}',()=>pm.expect(pm.response.code).to.be.oneOf([{','.join(str(x) for x in code)}]));"]
def req(name,m,path,actor,body,exp,label):
    h=[] if m=='POST' and 'login' in name.lower() else [{'key':'Authorization','value':'Bearer {{'+actor+'Token}}'}]
    if body is not None: h.append({'key':'Content-Type','value':'application/json'})
    tests=t(exp,label)
    if 'login admin' in name.lower(): tests += ["pm.environment.set('adminToken',pm.response.json().token);", "pm.environment.set('adminId',String(pm.response.json().user.id));"]
    if 'login user' in name.lower(): tests += ["pm.environment.set('userToken',pm.response.json().token);", "pm.environment.set('userId',String(pm.response.json().user.id));"]
    if 'checkout' in name.lower(): tests += ["pm.environment.set('orderId',String(pm.response.json().orderId));"]
    x={'name':name,'request':{'method':m,'header':h,'url':{'raw':'{{baseUrl}}'+path,'host':['{{baseUrl}}'],'path':path.strip('/').split('/')}},'event':[{'listen':'test','script':{'type':'text/javascript','exec':tests}}]}
    if body is not None: x['request']['body']={'mode':'raw','raw':json.dumps(body)}
    return x
coll={'info':{'name':'HW06 Member 4 — FR04 FR10 FR19','schema':'https://schema.getpostman.com/json/collection/v2.1.0/collection.json'},'event':[{'listen':'prerequest','script':{'type':'text/javascript','exec':pre}}],'variable':[{'key':'baseUrl','value':'http://localhost:3000'},{'key':'studentId','value':'23127326'}],'item':[]}
