    nums=[int(x) for x in expected.split('/') if x.isdigit()]
    if not nums: nums=[200]
    body=None
    if method=='PUT':
        body={'name':'Member Four','shipping_address':'Test','phone':'0912345678'} if feature=='FR04' else ({'status':'confirmed'} if feature=='FR10' else None)
        if feature=='FR04' and ('role' in data.lower() or 'escalat' in data.lower()): body['role']='admin'
    coll['item'].append({'name':tid+' — '+category,'description':f'{requirement}; {oracle}; audit={label}','request':req(tid,method,path,actor,body,nums,'case '+tid)['request'],'event':req(tid,method,path,actor,body,nums,'case '+tid)['event']})
